import React from 'react';
import { Helmet } from 'react-helmet';

// Type assertion: react-helmet types conflict when multiple @types/react versions are installed
const HelmetComponent = Helmet as React.ComponentType<any>;

export const DocumentTitle = ({ children, titleTemplatePrefix='BEES One' }: { children: string, titleTemplatePrefix?: string }): React.ReactElement => {
  return (
    <HelmetComponent titleTemplate={`${titleTemplatePrefix} - %s`}>
      <title>{children}</title>
    </HelmetComponent>
  );
};
