import React, { useMemo } from 'react';
import { IntlProvider as ReactIntlProvider } from 'react-intl';
import { usePreferredLanguageV2 } from '../hooks/usePreferredLanguageV2';
import { useTranslation } from '../hooks/useTranslation/useTranslation';
import { collectLocalesFromContext } from './collectLocalesFromContext';
import { isValidTmsResponse } from './isValidTmsResponse';
import { resolveFallbackMessages } from './resolveFallbackMessages';
import { stripTranslationPrefix } from './stripTranslationPrefix';
import { TmsIntlProviderConfig, TmsIntlProviderProps } from './types';

export function createTmsIntlProvider(config: TmsIntlProviderConfig) {
  const {
    mfe,
    translationPrefix,
    defaultLocale,
    localLanguagesContext,
    builtLocalesContext,
    enableBFF = true,
  } = config;

  const localMessages = collectLocalesFromContext(localLanguagesContext);
  const builtMessages = builtLocalesContext
    ? collectLocalesFromContext(builtLocalesContext)
    : {};

  function TmsIntlProvider({ children }: TmsIntlProviderProps): JSX.Element {
    const { preferredLanguage } = usePreferredLanguageV2();
    const locale = preferredLanguage || defaultLocale;

    const flattenedFallbackMessages = useMemo(
      () => resolveFallbackMessages(locale, defaultLocale, localMessages, builtMessages),
      [locale]
    );

    const { messages } = useTranslation({
      mfe,
      locale,
      fallbackMessages: flattenedFallbackMessages,
      enableBFF,
    });

    const resolvedMessages = useMemo(() => {
      if (isValidTmsResponse(messages, translationPrefix)) {
        return stripTranslationPrefix(messages, translationPrefix);
      }
      return flattenedFallbackMessages;
    }, [messages, flattenedFallbackMessages]);

    return (
      <ReactIntlProvider locale={locale} defaultLocale={defaultLocale} messages={resolvedMessages}>
        {children}
      </ReactIntlProvider>
    );
  }

  return TmsIntlProvider;
}
